void main() {
  final model = OnDeviceScamMLModel();

  test('Dart features == Python features', () {
    for (final g in _golden) {
      expect(model.extractFeatures(g.text), unorderedEquals(g.features), reason: g.text);
    }
  });

  test('Dart probability == Python probability (1e-6)', () {
    for (final g in _golden) {
      final r = model.predict(g.text);
      expect(r.probability, closeTo(g.prob, 1e-6), reason: g.text);
      expect((r.riskPercentage - g.risk).abs() <= 1, isTrue, reason: g.text);
    }
  });

  test('smoke: obvious scam locks (>=75), obvious safe does not', () {
    expect(model.predict('Usikate simu, tuma elfu kumi na tano kwa hii namba binafsi sasa hivi').riskPercentage, greaterThanOrEqualTo(75));
    expect(model.predict('Hello this is Equity Bank security, read me the OTP right now').riskPercentage, greaterThanOrEqualTo(75));
    expect(model.predict('Habari za asubuhi, tutaonana kesho kanisani').riskPercentage, lessThan(75));
    expect(model.predict('Equity Bank kamwe haitakuomba PIN au OTP kwa simu').riskPercentage, lessThan(75));
  });

  test('repeating a phrase barely changes the score (no length inflation)', () {
    final once = model.predict('tuma pesa').riskPercentage;
    final six = model.predict(List.filled(6, 'tuma pesa').join(' ')).riskPercentage;
    expect((six - once).abs(), lessThanOrEqualTo(3));
  });

  test('live retraining adds the sample and keeps an obvious scam above the lock line', () {
    final before = model.dataset.length;
    model.addSampleAndRetrain('Mwalimu anasema ada ya muhula ni elfu kumi, tutalipa kwa benki Ijumaa', 0, 'Safe');
    expect(model.dataset.length, equals(before + 1));
    expect(model.predict('Usikate simu, tuma elfu kumi na tano kwa hii namba binafsi sasa hivi').riskPercentage, greaterThanOrEqualTo(75));
  });
}